/* Biophilic — deep greens and earth tones, organic blob radii, soft natural light */
.theme-biophilic {
  --bg: oklch(0.96 0.018 110);
  --surface: oklch(0.99 0.012 110);
  --surface-2: oklch(0.92 0.03 120);
  --fg: oklch(0.26 0.045 150);
  --fg-muted: oklch(0.48 0.03 140);
  --accent: oklch(0.48 0.11 150);
  --accent-fg: oklch(0.98 0.012 110);
  --accent-2: oklch(0.66 0.11 65);
  --line: oklch(0.85 0.03 125);
  --success: oklch(0.55 0.13 150);
  --warning: oklch(0.72 0.14 75);
  --danger: oklch(0.52 0.15 35);

  --radius: 1.5rem;
  --radius-sm: 0.875rem;
  --radius-lg: 2.5rem 1.25rem 2.5rem 1.25rem;
  --radius-pill: 999px;

  --shadow-1: 0 2px 10px -4px oklch(0.3 0.06 150 / 0.25);
  --shadow-2: 0 10px 30px -12px oklch(0.3 0.06 150 / 0.3);
  --shadow-3: 0 24px 60px -20px oklch(0.3 0.06 150 / 0.35);
  --glow: 0 0 0 4px oklch(0.48 0.11 150 / 0.2);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Fraunces", Georgia, serif;
  --font-body: "Jost", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.015em;
  --label-transform: none;
  --label-tracking: 0.06em;

  background-color: var(--bg);
  background-image:
    radial-gradient(60% 45% at 12% 0%, oklch(0.8 0.1 150 / 0.35), transparent 70%),
    radial-gradient(50% 40% at 92% 12%, oklch(0.85 0.09 90 / 0.35), transparent 70%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-biophilic h1,
.theme-biophilic h2,
.theme-biophilic h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: var(--tracking-display);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
